\uses{def:qld-baseline-scalar-functions}
Set
\[
 \begin{aligned}
 C_{\mathrm{extract}}&=2800,\\
 C_{\mathrm{proj}}&=16C_{\mathrm{extract}}^2C_{\mathrm{pair}},
 &b_{\mathrm{proj}}&=b_{\mathrm{pair}}/16,\\
 C_{\mathrm{sound}}&=346\,21^3C_{\mathrm{proj}}^4,
 &b_{\mathrm{sound}}&=1/5242880000.
 \end{aligned}
\]
In particular $b_{\mathrm{proj}}=b_{\mathrm{sound}}$.
\end{definition}

\begin{theorem}[Explicit supplied-witness consistency estimates]
\label{thm:qld-supplied-global-consistency-explicit}
\lean{MIPStarRE.QPBT.global_marginal_encoding_consistency_explicit}
\lean{MIPStarRE.QPBT.tilde_m_consistent_point_meas_of_global_pair_witness_explicit}
\lean{MIPStarRE.QPBT.tilde_m_consistent_point_meas'_of_global_pair_witness_explicit}
\lean{MIPStarRE.QPBT.evaluated_pauli_tilde_consistency_of_global_pair_witness_explicit}
\lean{MIPStarRE.QPBT.tilde_obs_self_consistent_of_global_pair_witness_card}
\lean{MIPStarRE.QPBT.tilde_obs_self_consistent_of_global_pair_witness_explicit}
\lean{MIPStarRE.QPBT.extracted_obs_self_consistent_of_global_pair_witness_explicit}
\leanok
\uses{lem:qld-construct-the-paulis-given-global-pair,
def:qld-extraction-baseline-constants}
Let $\eps\geq0$, and suppose a projective setting $S$ is supplied with a global
polynomial-pair witness of error $\delta_G$.  For either basis, each evaluated
global marginal is consistent with the opposite encoding-supported reference
at error
\[
 \delta_G+(1+2\sqrt{172})\sqrt\eps.
\]
If moreover $\eps\leq1$ and $\delta_G\geq0$, the original point measurement
and the opposite pulled-apart measurement are consistent in both player
orientations at scale
\[
 \Delta_S(2+2\sqrt{172};\eps,\delta_G,m,d,q).
\]
The two evaluated total-Pauli measurements are consistent with the opposite
pulled-apart measurements at scale
\[
 \Delta_S(2+4\sqrt{172};\eps,\delta_G,m,d,q).
\]

For every basis coordinate $j$, the two pulled-apart observables have squared
distance at most
\[
 \Delta_S(48+32\lvert\mathcal E_{\mathrm{Pauli}}\rvert;
   \eps,\delta_G,m,d,q)
 =\Delta_S(C_{\mathrm{extract}};\eps,\delta_G,m,d,q).
\]
After conjugation by the concrete swap unitaries, the same bound holds for the
canonical Pauli observables on the extracted registers.  Every assertion in
this theorem retains the supplied global witness as a load-bearing hypothesis;
it is not a replacement for Lemma~\ref{lem:qld-construct-the-paulis}.
\end{theorem}
\begin{proof}
\leanok
Compare the global marginals with the encoding-supported references, bound
the mass outside the encoding by Schwartz--Zippel, and chain the point and
Pauli-basis consistency estimates.  Summing the fixed-edge terms gives
$48+32\cdot86=2800$, and unitary conjugation preserves the squared distance.
\end{proof}

\begin{theorem}[Explicit extraction from a supplied global witness]
\label{thm:qld-extraction-witness-explicit}
\lean{MIPStarRE.QPBT.exists_extraction_aux_of_global_pair_witness_explicit}
\lean{MIPStarRE.QPBT.exists_extraction_witness_of_global_pair_witness_explicit}
\lean{MIPStarRE.QPBT.delta_extract_le_delta_qld_explicit}
\lean{MIPStarRE.QPBT.exists_extraction_witness_explicit}
\leanok
\uses{thm:qld-supplied-global-consistency-explicit,
thm:qld-global-pair-witness-explicit, lem:qld-unitary}
Suppose $0\leq\eps\leq1$, $\delta_G\geq0$, and a projective setting is
supplied with a global polynomial-pair witness of error $\delta_G$.  There is
a unit auxiliary state for which the squared distance from the swapped state
to the ideal state is at most
\[
 16\Delta_S(C_{\mathrm{extract}};\eps,\delta_G,m,d,q).
\]
The two swap unitaries, this auxiliary state, and both Pauli-family estimates
form an extraction witness at error
\[
 \Delta_E\left(C_{\mathrm{extract}};
   \Delta_S(C_{\mathrm{extract}};\eps,\delta_G,m,d,q),m,d,q\right).
\]

For $C\geq1$, $a>1$, $0<b<1$, and $0\leq\eps\leq1$, the scalar extraction
error obeys
\[
 \Delta_E\bigl(C;\Delta_S(C;\eps,
   \delta_{\mathrm{qld}}(a,b,\eps,m,d,q),m,d,q),m,d,q\bigr)
 \leq\delta_{\mathrm{qld}}(4C^2a,b/8,\eps,m,d,q).
\]
In particular, substituting the global witness of
Theorem~\ref{thm:qld-global-pair-witness-explicit} constructs the extraction
witness internally with $C=C_{\mathrm{extract}}$ and
$\delta_G=\delta_{\mathrm{qld}}(C_{\mathrm{pair}},b_{\mathrm{pair}},
\eps,m,d,q)$.
\end{theorem}
\begin{proof}
\leanok
Project the swapped state onto the EPR factor, normalize the resulting
auxiliary vector, and use the explicit Pauli consistency estimate.  The scalar
comparison follows by subadditivity of the fourth root and admissibility
$md,q\geq1$.
\end{proof}

\begin{theorem}[Explicit projective and arbitrary-strategy isometry bounds]
\label{thm:qld-isometry-baselines-explicit}
\lean{MIPStarRE.QPBT.pauli_soundness_delta_qld_of_extraction_witness_explicit}
\lean{MIPStarRE.QPBT.projective_setting_isometry_bounds_explicit_baseline}
