\leanok
\uses{thm:qld-extraction-witness-explicit,
def:qld-extraction-baseline-constants}
For a projective setting with $0\leq\eps\leq1$, suppose a supplied global-pair
witness has error $\delta_{\mathrm{qld}}(a,b,\eps,m,d,q)$ and a supplied
extraction witness has coefficient $C$, where $C\geq1$, $a>1$, and
$0<b<1$.  Then the state distance and both complete Pauli-family squared
distances are bounded by
\[
 \delta_{\mathrm{qld}}(16C^2a,b/16,\eps,m,d,q).
\]
Therefore every projective setting in this error range satisfies all three
bounds with $(C_{\mathrm{proj}},b_{\mathrm{proj}})$.  For an arbitrary
strategy of value at least $1-\eps$, questionwise Naimark dilation gives the
same three complete-family conclusions with coefficient
$21C_{\mathrm{proj}}^2$ and power $b_{\mathrm{proj}}$.
\end{theorem}
\begin{proof}
\leanok
Pass from the swap unitaries to their range isometries, absorb the state square
root and the operator factor four, and then apply the Naimark reduction.  The
coefficient $21C_{\mathrm{proj}}^2$ absorbs the completed-family transfer.
\end{proof}

\begin{theorem}[Explicit raw-effect and qubit soundness]
\label{thm:pauli-soundness-explicit-baseline}
